import json
import os
import numpy as np
from pathlib import Path

RESULTS = Path("/root/persuasion_turn_jailbreak_detect/results")

def load_json(path):
    with open(path) as f:
        return json.load(f)

# ============================================================
# Task 1: Per-seed F1 macro (full turn) for each variant × OOD
# ============================================================

per_seed_f1 = {}

# --- 9-class DD OOD ---
# seed42: from per_sample predictions (all correct) → compute from plan files
# plan_002_eval has treatment results for seed42 IID, but DD OOD for seed42 is in the
# per_sample_predictions. Let's compute from predictions.
dd_preds = load_json(RESULTS / "per_sample_predictions/dd_ood_per_sample.json")
dd_labels = dd_preds["labels"]  # 80 jailbreak (1) + 38 benign (0) = 118

def compute_f1_macro(preds, labels):
    from sklearn.metrics import f1_score
    return f1_score(labels, preds, average='macro')

try:
    from sklearn.metrics import f1_score, recall_score, confusion_matrix
except ImportError:
    # Fallback manual implementation
    def f1_score(y_true, y_pred, average='macro'):
        classes = sorted(set(y_true) | set(y_pred))
        f1s = []
        for c in classes:
            tp = sum(1 for t, p in zip(y_true, y_pred) if t == c and p == c)
            fp = sum(1 for t, p in zip(y_true, y_pred) if t != c and p == c)
            fn = sum(1 for t, p in zip(y_true, y_pred) if t == c and p != c)
            prec = tp / (tp + fp) if (tp + fp) > 0 else 0
            rec = tp / (tp + fn) if (tp + fn) > 0 else 0
            f1 = 2 * prec * rec / (prec + rec) if (prec + rec) > 0 else 0
            f1s.append(f1)
        return np.mean(f1s)

    def recall_score(y_true, y_pred, pos_label=1, average=None):
        if average is None:
            classes = sorted(set(y_true) | set(y_pred))
            recs = []
            for c in classes:
                tp = sum(1 for t, p in zip(y_true, y_pred) if t == c and p == c)
                fn = sum(1 for t, p in zip(y_true, y_pred) if t == c and p != c)
                recs.append(tp / (tp + fn) if (tp + fn) > 0 else 0)
            return np.array(recs)
        else:
            tp = sum(1 for t, p in zip(y_true, y_pred) if t == pos_label and p == pos_label)
            fn = sum(1 for t, p in zip(y_true, y_pred) if t == pos_label and p != pos_label)
            return tp / (tp + fn) if (tp + fn) > 0 else 0

    def confusion_matrix(y_true, y_pred):
        classes = sorted(set(y_true) | set(y_pred))
        n = len(classes)
        cm = np.zeros((n, n), dtype=int)
        c2i = {c: i for i, c in enumerate(classes)}
        for t, p in zip(y_true, y_pred):
            cm[c2i[t]][c2i[p]] += 1
        return cm

# ---- 9-class ----
nine_class_dd = {}
for seed in ["42", "123", "456"]:
    preds = dd_preds["preds"]["9class"][seed]["full"]
    nine_class_dd[seed] = round(f1_score(dd_labels, preds, average='macro'), 6)

# plan_002 DD OOD files for cross-validation
p002_s123 = load_json(RESULTS / "plan_002_seed123_dd_ood.json")
p002_s456 = load_json(RESULTS / "plan_002_seed456_dd_ood.json")

per_seed_f1["9-class"] = {
    "DD": {42: nine_class_dd["42"], 123: nine_class_dd["123"], 456: nine_class_dd["456"]},
    "AA": {},
    "FITD": {}
}

# 9-class AA OOD from exp2_actorattack_ood.json
aa_data = load_json(RESULTS / "exp2_actorattack_ood.json")
for v_key, v_name in [("9class", "9-class"), ("binary", "Binary"), ("scrambled", "Scrambled"),
                        ("mlm", "MLM+cls"), ("topic", "Topic"), ("vanilla", "Vanilla")]:
    if v_key in aa_data["variant_results"]:
        ps = aa_data["variant_results"][v_key]["per_seed"]
        if v_name not in per_seed_f1:
            per_seed_f1[v_name] = {"DD": {}, "AA": {}, "FITD": {}}
        for seed in ["42", "123", "456"]:
            if seed in ps:
                per_seed_f1[v_name]["AA"][int(seed)] = round(ps[seed]["full"], 6)

# 9-class FITD OOD from exp25
fitd_data = load_json(RESULTS / "exp25_fitd_early_detection.json")
for v_key, v_name in [("9class", "9-class"), ("mlm", "MLM+cls"), ("vanilla", "Vanilla")]:
    if v_key in fitd_data["variant_results"]:
        ps = fitd_data["variant_results"][v_key]["per_seed"]
        if v_name not in per_seed_f1:
            per_seed_f1[v_name] = {"DD": {}, "AA": {}, "FITD": {}}
        for seed in ["42", "123", "456"]:
            if seed in ps:
                per_seed_f1[v_name]["FITD"][int(seed)] = round(ps[seed]["full"], 6)

# ---- Binary DD OOD ----
if "Binary" not in per_seed_f1:
    per_seed_f1["Binary"] = {"DD": {}, "AA": {}, "FITD": {}}

b_s123 = load_json(RESULTS / "mf1_binary_seed123.json")
per_seed_f1["Binary"]["DD"][123] = round(b_s123["dd_ood"]["full"]["f1_macro"], 6)

b_s456 = load_json(RESULTS / "mf1_binary_seed456.json")
per_seed_f1["Binary"]["DD"][456] = round(b_s456["results"]["full"]["f1_macro"], 6)

# Binary seed42 DD OOD: check per_sample_predictions
if "binary" in dd_preds["preds"]:
    for seed in ["42", "123", "456"]:
        if seed in dd_preds["preds"]["binary"]:
            preds = dd_preds["preds"]["binary"][seed]["full"]
            per_seed_f1["Binary"]["DD"][int(seed)] = round(f1_score(dd_labels, preds, average='macro'), 6)

# ---- Scrambled DD OOD ----
if "Scrambled" not in per_seed_f1:
    per_seed_f1["Scrambled"] = {"DD": {}, "AA": {}, "FITD": {}}

scr_s42 = load_json(RESULTS / "plan_003_scrambled_fix.json")
per_seed_f1["Scrambled"]["DD"][42] = round(scr_s42["dd_ood_results"]["full"]["f1_macro"], 6)

scr_s123 = load_json(RESULTS / "mf1_scrambled_seed123.json")
per_seed_f1["Scrambled"]["DD"][123] = round(scr_s123["dd_ood_results"]["full"]["f1_macro"], 6)

scr_s456 = load_json(RESULTS / "mf1_scrambled_seed456.json")
per_seed_f1["Scrambled"]["DD"][456] = round(scr_s456["dd_ood_results"]["full"]["f1_macro"], 6)

# Scrambled AA seed123 from exp2_missing_seeds_complete
miss = load_json(RESULTS / "exp2_missing_seeds_complete.json")
if "scrambled_seed123" in miss:
    per_seed_f1["Scrambled"]["AA"][123] = round(miss["scrambled_seed123"]["full"], 6)

# ---- MLM+cls DD OOD ----
if "MLM+cls" not in per_seed_f1:
    per_seed_f1["MLM+cls"] = {"DD": {}, "AA": {}, "FITD": {}}

mlm_s42 = load_json(RESULTS / "plan_017_mlm_control.json")
per_seed_f1["MLM+cls"]["DD"][42] = round(mlm_s42["dd_ood_results"]["full"]["f1_macro"], 6)

mlm_s123 = load_json(RESULTS / "plan_017_mlm_seed123.json")
per_seed_f1["MLM+cls"]["DD"][123] = round(mlm_s123["dd_ood_results"]["full"]["f1_macro"], 6)

mlm_s456 = load_json(RESULTS / "plan_017_mlm_seed456.json")
per_seed_f1["MLM+cls"]["DD"][456] = round(mlm_s456["dd_ood_results"]["full"]["f1_macro"], 6)

# MLM AA OOD from exp2
if "mlm" in aa_data["variant_results"]:
    ps = aa_data["variant_results"]["mlm"]["per_seed"]
    for seed in ["42", "123", "456"]:
        if seed in ps:
            per_seed_f1["MLM+cls"]["AA"][int(seed)] = round(ps[seed]["full"], 6)

# ---- Topic DD OOD ----
if "Topic" not in per_seed_f1:
    per_seed_f1["Topic"] = {"DD": {}, "AA": {}, "FITD": {}}

for seed in [42, 123, 456]:
    t = load_json(RESULTS / f"plan_016v2_topic_seed{seed}.json")
    per_seed_f1["Topic"]["DD"][seed] = round(t["dd_results"]["full"]["f1_macro"], 6)

# Topic AA OOD from exp2
if "topic" in aa_data["variant_results"]:
    ps = aa_data["variant_results"]["topic"]["per_seed"]
    for seed in ["42", "123", "456"]:
        if seed in ps:
            per_seed_f1["Topic"]["AA"][int(seed)] = round(ps[seed]["full"], 6)

# ---- Vanilla DD OOD ----
if "Vanilla" not in per_seed_f1:
    per_seed_f1["Vanilla"] = {"DD": {}, "AA": {}, "FITD": {}}

van_dd = load_json(RESULTS / "vanilla_multiseed_dd_ood.json")
per_seed_f1["Vanilla"]["DD"][42] = round(van_dd["seed42"]["full"], 6)
per_seed_f1["Vanilla"]["DD"][123] = round(van_dd["seed123"]["full"], 6)
per_seed_f1["Vanilla"]["DD"][456] = round(van_dd["seed456"]["full"], 6)

# Vanilla AA OOD from exp2
if "vanilla" in aa_data["variant_results"]:
    ps = aa_data["variant_results"]["vanilla"]["per_seed"]
    for seed in ["42", "123", "456"]:
        if seed in ps:
            per_seed_f1["Vanilla"]["AA"][int(seed)] = round(ps[seed]["full"], 6)

# ---- FITD: check per_sample_predictions for additional variants ----
fitd_preds_path = RESULTS / "per_sample_predictions/fitd_ood_per_sample.json"
if fitd_preds_path.exists():
    fitd_preds = load_json(fitd_preds_path)
    fitd_labels = fitd_preds["labels"]
    for v_key, v_name in [("binary", "Binary"), ("scrambled", "Scrambled"), ("topic", "Topic")]:
        if v_key in fitd_preds.get("preds", {}):
            ps = fitd_preds["preds"][v_key]
            for seed in ["42", "123", "456"]:
                if seed in ps:
                    preds = ps[seed]["full"]
                    per_seed_f1[v_name]["FITD"][int(seed)] = round(
                        f1_score(fitd_labels, preds, average='macro'), 6)

# Also check Binary/Scrambled FITD from exp25
for v_key, v_name in [("binary", "Binary"), ("scrambled", "Scrambled"), ("topic", "Topic")]:
    if v_key in fitd_data["variant_results"]:
        ps = fitd_data["variant_results"][v_key]["per_seed"]
        for seed in ["42", "123", "456"]:
            if seed in ps and int(seed) not in per_seed_f1.get(v_name, {}).get("FITD", {}):
                per_seed_f1[v_name]["FITD"][int(seed)] = round(ps[seed]["full"], 6)

# ============================================================
# Task 2: Cohen's d (9-class vs Scrambled)
# ============================================================

def cohens_d(x, y):
    mx, my = np.mean(x), np.mean(y)
    sx, sy = np.std(x, ddof=0), np.std(y, ddof=0)
    pooled = np.sqrt((sx**2 + sy**2) / 2)
    if pooled == 0:
        return float('inf') if mx != my else 0.0
    return (mx - my) / pooled

seeds = [42, 123, 456]

nine_dd = [per_seed_f1["9-class"]["DD"].get(s, None) for s in seeds]
scr_dd = [per_seed_f1["Scrambled"]["DD"].get(s, None) for s in seeds]

nine_aa = [per_seed_f1["9-class"]["AA"].get(s, None) for s in seeds]
scr_aa = [per_seed_f1["Scrambled"]["AA"].get(s, None) for s in seeds]

cohens_d_results = {}

if all(v is not None for v in nine_dd + scr_dd):
    d_dd = cohens_d(nine_dd, scr_dd)
    cohens_d_results["DD"] = {
        "d": round(d_dd, 4),
        "9class_values": nine_dd,
        "scrambled_values": scr_dd,
        "9class_mean": round(np.mean(nine_dd), 4),
        "scrambled_mean": round(np.mean(scr_dd), 4),
        "n": 3,
        "note": "n=3, CI is wide"
    }
else:
    cohens_d_results["DD"] = {"d": "N/A", "note": "Missing data"}

if all(v is not None for v in nine_aa + scr_aa):
    d_aa = cohens_d(nine_aa, scr_aa)
    cohens_d_results["AA"] = {
        "d": round(d_aa, 4),
        "9class_values": nine_aa,
