per_seed_recall = {}

def compute_recalls(preds_list, labels_list):
    preds = np.array(preds_list)
    labels = np.array(labels_list)
    # Attack = 1, Benign = 0
    attack_mask = labels == 1
    benign_mask = labels == 0
    attack_recall = np.mean(preds[attack_mask] == 1) if attack_mask.sum() > 0 else None
    benign_recall = np.mean(preds[benign_mask] == 0) if benign_mask.sum() > 0 else None
    return round(float(attack_recall), 6) if attack_recall is not None else None, \
           round(float(benign_recall), 6) if benign_recall is not None else None

